<?php
require __DIR__ . '/../app/bootstrap.php';
$u=require_role(['reseller']);$s=$db->prepare('SELECT id FROM resellers WHERE user_id=? LIMIT 1');$s->execute([$u['id']]);$rid=(int)$s->fetchColumn();$msg=null;$error=null;
$s=$db->prepare('SELECT * FROM white_label_settings WHERE reseller_id=?');$s->execute([$rid]);$w=$s->fetch()?:['company_name'=>'','logo_url'=>'','support_email'=>'','website_url'=>'','brand_color'=>'','custom_domain'=>'','enabled'=>0];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$db->prepare('INSERT INTO white_label_settings(reseller_id,company_name,logo_url,support_email,website_url,brand_color,custom_domain,enabled) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE company_name=VALUES(company_name),logo_url=VALUES(logo_url),support_email=VALUES(support_email),website_url=VALUES(website_url),brand_color=VALUES(brand_color),custom_domain=VALUES(custom_domain),enabled=VALUES(enabled)')->execute([$rid,trim($_POST['company_name']),trim($_POST['logo_url']),trim($_POST['support_email']),trim($_POST['website_url']),trim($_POST['brand_color']),trim($_POST['custom_domain']),isset($_POST['enabled'])?1:0]);$msg='White-label settings saved.';}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>White Label — SkyNoc</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fb;font-family:Inter,system-ui,sans-serif;color:#0f172a}.wrap{max-width:700px;margin:30px auto;padding:14px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:18px;padding:22px}input,button{width:100%;padding:12px;margin:6px 0;border:1px solid #dbe2ea;border-radius:9px}button{background:#111827;color:#fff;border:0;font-weight:700}.msg{background:#ecfdf5;color:#166534;padding:10px}.err{background:#fef2f2;color:#991b1b;padding:10px}.check{width:auto}.hint{color:#64748b;font-size:13px}</style></head><body><main class="wrap"><div class="card"><a href="/reseller">← Back to reseller panel</a><h1>White-label Branding</h1><p class="hint">These settings are exposed only through your own scoped API. A custom domain requires DNS/SSL configuration separately.</p><?php if($msg):?><p class="msg"><?=e($msg)?></p><?php endif;?><?php if($error):?><p class="err"><?=e($error)?></p><?php endif;?><form method="post"><?=csrf_field()?><label><input class="check" type="checkbox" name="enabled" <?=$w['enabled']?'checked':''?>> Enable white-label profile</label><input name="company_name" value="<?=e($w['company_name'])?>" placeholder="Company name"><input name="logo_url" value="<?=e($w['logo_url'])?>" placeholder="Logo URL"><input name="support_email" value="<?=e($w['support_email'])?>" placeholder="Support email"><input name="website_url" value="<?=e($w['website_url'])?>" placeholder="Website URL"><input name="brand_color" value="<?=e($w['brand_color'])?>" placeholder="#111827"><input name="custom_domain" value="<?=e($w['custom_domain'])?>" placeholder="portal.example.com"><button>Save Branding</button></form></div></main></body></html>